window.kbPageData["views/entry/k-635a61276555a56b"] = {"key":"entry/k-635a61276555a56b","state":{"route":"entry/k-635a61276555a56b"},"node":{"id":"k-635a61276555a56b","mode":"k","title":"2026 年经济社会发展总体要求和政策取向","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"四、2026 年经济社会发展总体要求和政策取向\n今年是“十五五”开局之年。做好政府工作，要在以习近平同志为核心的党中央坚强领\n导下，以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全\n会精神，认真落实党的二十届四中全会和中央经济工作会议部署，完整准确全面贯彻新发展\n理念①，加…","sources":[{"id":"a2ac53289746886e","label":"2026 年经济社会发展总体要求和政策取向","topic":"年度政府工作","category":"时政","text":"四、2026 年经济社会发展总体要求和政策取向\n今年是“十五五”开局之年。做好政府工作，要在以习近平同志为核心的党中央坚强领\n导下，以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全\n会精神，认真落实党的二十届四中全会和中央经济工作会议部署，完整准确全面贯彻新发展\n理念①，加快构建新发展格局，着力推动高质量发展，坚持稳中求进工作总基调，统筹国内\n国际两个大局，更好统筹发展和安全，实施更加积极有为的宏观政策，增强政策前瞻性针\n对性协同性，持续扩大内需、优化供给，做优增量、盘活存量，因地制宜发展新质生产力，\n纵深推进全国统一大市场建设，持续防范化解重点领域风险，着力稳就业、稳企业、稳市\n场、稳预期，推动经济实现质的有效提升和量的合理增长，保持社会和谐稳定，实现“十\n五五”良好开局。","source":{"doc":"6cbfb01fe723bba64b75","first":21,"last":21,"page":21,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-635a61276555a56b":[]}};
